async def _demo() -> None:
    """
    Self-test: attempt pg_notify path, fall back to polling, report timing.
    """
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(name)s] %(levelname)s: %(message)s",
    )
    conv_id = "demo_conv_001"

    print("=" * 60)
    print("Dashboard reply-polling → pg_notify demo")
    print("=" * 60)

    # Try to set up the trigger
    print("\n[1] Setting up pg_notify trigger...")
    trigger_ok = await setup_notify_trigger()
    print(f"    Trigger installed: {trigger_ok}")

    # Start a background task that simulates a reply after 5s
    async def simulate_reply(delay: float) -> None:
        await asyncio.sleep(delay)
        print(f"\n    >> Simulated reply arriving after {delay}s")
        await notify_reply(
            conversation_id=conv_id,
            message_id="msg_demo_001",
            agent_name="test-agent",
            content="Hello from the notify demo!",
        )

    sim_task = asyncio.create_task(simulate_reply(5.0))

    # Wait for reply via the unified API
    print(f"\n[2] Waiting for reply (conv={conv_id}, timeout=30s)...")
    t0 = time.monotonic()
    reply = await wait_for_reply(conv_id, timeout=30.0)
    elapsed = time.monotonic() - t0

    if reply:
        print(f"\n[3] ✓ Reply received in {elapsed:.2f}s")
        print(f"    agent:   {reply.agent_name}")
        print(f"    content: {reply.content}")
        print(f"    msg_id:  {reply.message_id}")
    else:
        print(f"\n[3] ✗ No reply received after {elapsed:.2f}s")

    await sim_task
    await shutdown_listener()
    print("\nDone.")


if __name__ == "__main__":
    asyncio.run(_demo())